**Gates before launch**

I save the script below as `spe/evals/harness/r04-workflow.js` and commit it locally with the message `spe r04: evaluate harness`. I do not push. Then I run four gates in order, and I stop and report at the first one that fails. Gate 1: `git log -1 -- spe/predictions/r04.yaml` shows the commit from 10 minutes ago, and `git diff --quiet HEAD -- spe/predictions/r04.yaml` shows that nobody edited the file after it. Gate 2 is the grader selftest. `grade.py` must score the oracle (answers.json graded against itself) fully correct. An empty results file must fail, and so must a file with every label moved to a wrong value. This gate also counts the entries in answers.json. The plan says 50 tickets, but the original eval set had 40, so if the count is not 50 I halt and ask you. Gate 3 is the control. I regrade round 3's saved results in `spe/evals/results/r03.json` with this round's `grade.py` and compare them with round 3's recorded scores. Any difference comes from a grader change, not an agent change. I log it in `spe/failures.md` before launch and leave `r04.yaml` untouched. Gate 4 is a dry run of this script with `only: ["B:T001", "C2:T001", "C2:T037"]`, `trials: 1`, and `capUsd: 2`. It must return schema-valid trials with a runner cost on each trial, a grade and a tone score for each trial, and zero voided trials. If all four gates pass, I launch the full run with the args in the script header.

**spe/evals/harness/r04-workflow.js**

```js
export const meta = {
  name: 'triage-spe-eval',
  description: 'SPE evaluate step for the triage agent. Runs every config on every ticket for N trials, voids trials that touch spe/, grades labels with spe/evals/graders/grade.py, tops up mixed cells, judges reply tone with an Opus judge, then runs failure analysis and a completeness critic. Round, configs, tickets, and caps come from args.',
  phases: ['Trials', 'Leak scan', 'Grade', 'Top-up', 'Judge', 'Synthesis'],
};

// Defaults kept from spe/evals/harness/r03-workflow.js:
// - Each trial runs the triage runner once:
//     python -m triage.run --config <CONFIG> --ticket spe/evals/tasks/tickets/<TICKET>.json --json
//   It prints {label:{category,priority}, reply, usage:{input_tokens,output_tokens,cost_usd}, runtime_ms, tool_calls:[{name,args,error}]}.
// - grade.py takes --answers <file> --results <file> --json and prints [{trial_id, category_ok, priority_ok}].
// - A trial may touch only its own ticket file under spe/. Any other spe/ path voids the trial.
// - capUsd covers triage API spend reported by the runner, plus estimates for grader, judge, and helper agents.
//
// Full launch args:
// {
//   "round": "r04",
//   "configs": ["B", "C2"],
//   "tickets": [the 50 ids listed from spe/evals/tasks/tickets/ at launch],
//   "trials": 5,
//   "capUsd": 40,
//   "est": {"trialUsd": 0.04, "gradeUsd": 0.10, "judgeUsd": 0.20, "helperUsd": 0.15},  // estimates, not measured
//   "topUp": {"perCell": 3, "maxTrials": 40},
//   "transcriptRoot": "~/.claude/projects"
// }
// Dry run: the same args plus "only": ["B:T001", "C2:T001", "C2:T037"], "trials": 1, "capUsd": 2.

// ---------- Arguments ----------
const ROUND = args.round;
if (!/^r\d{2}$/.test(ROUND ?? '')) throw new Error('args.round is required and must look like "r04"');
const NEXT_ROUND = 'r' + String(Number(ROUND.slice(1)) + 1).padStart(2, '0');

const CONFIGS = args.configs;
const TICKETS = args.tickets;
const ONLY = Array.isArray(args.only) ? new Set(args.only) : null;
if (!Array.isArray(CONFIGS) || CONFIGS.length === 0) throw new Error('args.configs is required');
if (!Array.isArray(TICKETS) || TICKETS.length === 0) throw new Error('args.tickets is required');
const EXPECT_TICKETS = args.expectTickets ?? 50;
if (!ONLY && TICKETS.length !== EXPECT_TICKETS) {
  throw new Error(`expected ${EXPECT_TICKETS} tickets, got ${TICKETS.length}`);
}
if (!args.transcriptRoot) throw new Error('args.transcriptRoot is required for the leak scan');

const TRIALS = args.trials ?? 5;
const CAP_USD = args.capUsd ?? 40;
const EST = { trialUsd: 0.04, gradeUsd: 0.1, judgeUsd: 0.2, helperUsd: 0.15, ...(args.est ?? {}) };
const TOPUP = { perCell: 3, maxTrials: 40, ...(args.topUp ?? {}) };
const HELPER_MODEL = args.helperModel ?? 'opus';
const JUDGE_MODEL = args.judgeModel ?? 'opus';

const TICKET_DIR = 'spe/evals/tasks/tickets';
const GRADER = 'spe/evals/graders/grade.py';
const ANSWERS = 'spe/evals/tasks/answers.json';
const JUDGE_RUBRIC = 'spe/evals/graders/judge.md';
const PREDICTIONS = `spe/predictions/${ROUND}.yaml`;
const PLAN = `spe/plans/${ROUND}.md`;
const ticketPath = (t) => `${TICKET_DIR}/${t}.json`;
const cellKey = (c, t) => `${c}:${t}`;
const trialId = (c, t, n) => `${ROUND}-${c}-${t}-t${n}`;

if (ONLY) {
  for (const key of ONLY) {
    const [c, t] = key.split(':');
    if (!CONFIGS.includes(c) || !TICKETS.includes(t)) throw new Error(`args.only entry ${key} is not a known cell`);
  }
}

// ---------- State, budget, halt ----------
let trials = [];
let topups = [];
let halt = null;
let toneScaleMax = null;
const budget = { capUsd: CAP_USD, spentUsd: 0, reservedUsd: 0, skipped: [] };

function stop(reason, detail) {
  if (!halt) {
    halt = { reason, detail };
    log(`HALT ${reason}: ${detail}`);
  }
}

function reserve(kind, id, est) {
  if (halt) {
    budget.skipped.push({ kind, id, why: `halted: ${halt.reason}` });
    return false;
  }
  if (budget.spentUsd + budget.reservedUsd + est > CAP_USD) {
    budget.skipped.push({ kind, id, why: 'cap', estUsd: est });
    log(`budget: skipped ${kind} ${id}. Spent $${budget.spentUsd.toFixed(2)}, reserved $${budget.reservedUsd.toFixed(2)}, cap $${CAP_USD}.`);
    stop('budget-cap', `first skip was ${kind} ${id}`);
    return false;
  }
  budget.reservedUsd += est;
  return true;
}

function settle(est, actualUsd) {
  budget.reservedUsd -= est;
  budget.spentUsd += typeof actualUsd === 'number' ? actualUsd : est;
}

// ---------- Schemas ----------
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['trial_id', 'status', 'runner_exit_code', 'files_read'],
  properties: {
    trial_id: { type: 'string' },
    status: { type: 'string', enum: ['completed', 'harness_error', 'rate_limited'] },
    runner_exit_code: { type: 'integer' },
    error: { type: 'string' },
    label: {
      type: ['object', 'null'],
      properties: { category: { type: ['string', 'null'] }, priority: { type: ['string', 'null'] } },
    },
    reply: { type: ['string', 'null'] },
    usage: {
      type: 'object',
      properties: {
        input_tokens: { type: 'integer' },
        output_tokens: { type: 'integer' },
        cost_usd: { type: 'number' },
      },
    },
    runtime_ms: { type: 'integer' },
    tool_calls: {
      type: 'array',
      items: {
        type: 'object',
        required: ['name'],
        properties: { name: { type: 'string' }, args: { type: 'string' }, error: { type: 'boolean' } },
      },
    },
    files_read: { type: 'array', items: { type: 'string' } },
  },
};

const SCAN_SCHEMA = {
  type: 'object',
  required: ['transcripts_scanned', 'hits'],
  properties: {
    transcripts_scanned: { type: 'integer' },
    hits: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial_id', 'path'],
        properties: { trial_id: { type: 'string' }, tool: { type: 'string' }, path: { type: 'string' } },
      },
    },
  },
};

const GRADE_SCHEMA = {
  type: 'object',
  required: ['exit_code', 'results'],
  properties: {
    exit_code: { type: 'integer' },
    stderr_tail: { type: 'string' },
    results: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial_id', 'category_ok', 'priority_ok'],
        properties: {
          trial_id: { type: 'string' },
          category_ok: { type: 'boolean' },
          priority_ok: { type: 'boolean' },
        },
      },
    },
  },
};

const JUDGE_SCHEMA = {
  type: 'object',
  required: ['scale_max', 'scores'],
  properties: {
    scale_max: { type: 'number' },
    scores: {
      type: 'array',
      items: {
        type: 'object',
        required: ['reply_id', 'tone', 'rationale'],
        properties: { reply_id: { type: 'string' }, tone: { type: 'number' }, rationale: { type: 'string' } },
      },
    },
  },
};

const ANALYSIS_SCHEMA = {
  type: 'object',
  required: ['prediction_scores', 'all_hit', 'ceiling', 'failures', 'proposals'],
  properties: {
    prediction_scores: {
      type: 'array',
      items: {
        type: 'object',
        required: ['metric', 'config', 'predicted', 'band', 'observed', 'verdict', 'grader_check'],
        properties: {
          metric: { type: 'string' },
          config: { type: 'string' },
          predicted: { type: 'number' },
          band: { type: 'number' },
          observed: { type: ['number', 'null'] },
          verdict: { type: 'string', enum: ['hit', 'miss', 'not_scorable'] },
          grader_check: { type: 'string' },
        },
      },
    },
    all_hit: { type: 'boolean' },
    ceiling: { type: 'boolean' },
    failures: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'title', 'trial_ids', 'cause'],
        properties: {
          id: { type: 'string' },
          title: { type: 'string' },
          trial_ids: { type: 'array', items: { type: 'string' } },
          cause: { type: 'string' },
        },
      },
    },
    proposals: {
      type: 'array',
      items: {
        type: 'object',
        required: ['change', 'reason', 'failure_ids'],
        properties: {
          change: { type: 'string' },
          reason: { type: 'string' },
          failure_ids: { type: 'array', items: { type: 'string' } },
        },
      },
    },
  },
};

const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'gaps'],
  properties: { complete: { type: 'boolean' }, gaps: { type: 'array', items: { type: 'string' } } },
};

// ---------- Trials ----------
const trialPrompt = (id, config, ticket) => `You are a harness driver for one trial of the triage agent. Do these steps and nothing else.

trial_id: ${id}

1. From the repository root, run this command once:
   python -m triage.run --config ${config} --ticket ${ticketPath(ticket)} --json
2. Map the JSON it prints onto the result schema. Copy label, reply, usage, runtime_ms, and tool_calls exactly as printed. Put each tool call's arguments in "args" as a JSON string. Do not fix, rerun, or judge the output.

Rules:
- You may pass ${ticketPath(ticket)} to the command. Do not open, list, search, or print any path under spe/. Do not open files under triage/. The command reads what it needs.
- If the command exits non-zero, set status "harness_error", set runner_exit_code, and put the last line of stderr in error. If the error mentions HTTP 429, overloaded, or rate limit, set status "rate_limited" instead. Do not retry.
- If the command exits 0, set status "completed", even when the label or reply is missing or looks wrong.
- List in files_read every file you opened or searched yourself. Use an empty list if you opened none.`;

async function runTrial({ config, ticket, n, phaseName }) {
  const id = trialId(config, ticket, n);
  let r = null;
  for (let attempt = 1; attempt <= 2; attempt++) {
    if (!reserve('trial', id, EST.trialUsd)) return { trial_id: id, config, ticket, n, phase: phaseName, status: 'skipped' };
    try {
      r = await agent(trialPrompt(id, config, ticket), {
        label: attempt === 1 ? id : `${id}-retry`,
        phase: phaseName,
        schema: TRIAL_SCHEMA,
        model: HELPER_MODEL,
      });
    } catch (e) {
      r = { status: 'harness_error', error: String(e?.message ?? e) };
    }
    settle(EST.trialUsd, r?.usage?.cost_usd);
    r = { ...r, trial_id: id, config, ticket, n, attempt, phase: phaseName };
    if (r.status === 'completed') return r;
    log(`trial ${id} attempt ${attempt}: ${r.status}${r.error ? ` (${r.error})` : ''}`);
  }
  return r; // harness errors and rate limits are not model failures
}

function voidIfPeeked(r) {
  if (r.status !== 'completed') return r;
  const own = ticketPath(r.ticket);
  const seen = [
    ...(r.files_read ?? []),
    ...(r.tool_calls ?? []).map((t) => `${t.name} ${t.args ?? ''}`),
  ];
  const hits = seen.filter((s) => s.split(own).join('').includes('spe/'));
  if (hits.length) {
    log(`VOID ${r.trial_id}: touched ${hits.join(' | ')}`);
    stop('answer-key-read', `${r.trial_id} touched ${hits[0]}`);
    return { ...r, voided: true, void_reason: hits };
  }
  return r;
}

// ---------- Leak scan over driver transcripts ----------
async function transcriptScan(list, phaseName) {
  const ids = list.filter((t) => t.status === 'completed' && !t.voided).map((t) => t.trial_id);
  if (!ids.length) return;
  if (!reserve('leak-scan', phaseName, EST.helperUsd)) return;
  let scan;
  try {
    scan = await agent(`You check trial transcripts for peeks at the answer key. Do not open any file under spe/ yourself.

1. Under ${args.transcriptRoot}, find Claude Code transcript files (.jsonl) modified in the last ${args.scanHours ?? 24} hours whose first user message starts with "You are a harness driver for one trial of the triage agent" and contains "trial_id: ${ROUND}-".
2. In each one, read the trial_id line. Then check every tool call (Read, Grep, Glob, Bash, and any other tool) for a path under spe/.
3. A hit is any spe/ path other than ${TICKET_DIR}/<TICKET>.json, where <TICKET> comes from that transcript's trial_id. The trial_id format is ${ROUND}-<CONFIG>-<TICKET>-t<N>.
4. Return every hit with its trial_id, tool name, and path. Set transcripts_scanned to the number of matching transcripts.

Expected trial_ids (${ids.length}): ${ids.join(', ')}`, {
      label: `leak-scan-${phaseName}`,
      phase: 'Leak scan',
      schema: SCAN_SCHEMA,
      model: HELPER_MODEL,
    });
  } catch (e) {
    settle(EST.helperUsd);
    stop('leak-scan-failed', String(e?.message ?? e));
    return;
  }
  settle(EST.helperUsd);
  if (scan.transcripts_scanned < ids.length) {
    stop('leak-scan-incomplete', `found ${scan.transcripts_scanned} transcripts for ${ids.length} trials`);
  }
  const byId = new Map(list.map((t) => [t.trial_id, t]));
  for (const h of scan.hits) {
    const t = byId.get(h.trial_id);
    if (t && !t.voided) {
      t.voided = true;
      t.void_reason = [`${h.tool ?? 'tool'} ${h.path}`];
      log(`VOID ${t.trial_id}: transcript shows ${h.tool ?? 'tool'} on ${h.path}`);
      stop('answer-key-read', `${t.trial_id} touched ${h.path}`);
    }
  }
}

// ---------- Code grader ----------
async function gradeTrials(list, phaseName) {
  const todo = list.filter((t) => t.status === 'completed' && !t.voided && !t.grade);
  const batches = [];
  for (let i = 0; i < todo.length; i += 50) batches.push(todo.slice(i, i + 50));
  const outs = await parallel(batches.map((batch, b) => async () => {
    const tag = `${phaseName}-${b + 1}`;
    if (!reserve('grade', tag, EST.gradeUsd)) return null;
    const input = batch.map((t) => ({ trial_id: t.trial_id, ticket: t.ticket, label: t.label ?? null }));
    const file = `/tmp/triage-${ROUND}-grade-${tag}.json`;
    try {
      const out = await agent(`Run the code grader on these trial results. Do not grade anything yourself. Do not edit the grader or the answer file.

1. Write the JSON array below, unchanged, to ${file}.
2. Run: python ${GRADER} --answers ${ANSWERS} --results ${file} --json
3. Return the exit code, the last 5 lines of stderr as stderr_tail, and the printed JSON array as results, unchanged.

${JSON.stringify(input)}`, { label: `grade-${tag}`, phase: 'Grade', schema: GRADE_SCHEMA, model: HELPER_MODEL });
      settle(EST.gradeUsd);
      return { tag, batch, out };
    } catch (e) {
      settle(EST.gradeUsd);
      return { tag, batch, out: null, error: String(e?.message ?? e) };
    }
  }));
  for (const o of outs) {
    if (!o) continue;
    if (!o.out || o.out.exit_code !== 0) {
      stop('grader-broken', `batch ${o.tag}: ${o.error ?? o.out?.stderr_tail ?? 'non-zero exit'}`);
      continue;
    }
    const byId = new Map(o.out.results.map((g) => [g.trial_id, g]));
    for (const t of o.batch) {
      const g = byId.get(t.trial_id);
      if (!g) {
        stop('grader-broken', `no grade returned for ${t.trial_id}`);
        continue;
      }
      t.grade = { category_ok: g.category_ok, priority_ok: g.priority_ok, pass: g.category_ok && g.priority_ok };
    }
  }
}

// ---------- Helpers ----------
const mean = (xs) => {
  const v = xs.filter(Number.isFinite);
  return v.length ? v.reduce((a, b) => a + b, 0) / v.length : null;
};
const r3 = (x) => (x == null ? null : Math.round(x * 1000) / 1000);
const done = (t) => t.status === 'completed' && !t.voided;

function seeded(str) {
  let h = 2166136261;
  for (const ch of str) {
    h ^= ch.charCodeAt(0);
    h = Math.imul(h, 16777619);
  }
  if (h === 0) h = 1;
  return () => {
    h ^= h << 13;
    h ^= h >>> 17;
    h ^= h << 5;
    return (h >>> 0) / 4294967296;
  };
}

const compact = (t) => ({
  trial_id: t.trial_id, config: t.config, ticket: t.ticket, n: t.n, phase: t.phase, attempt: t.attempt,
  status: t.status, error: t.error, voided: !!t.voided, void_reason: t.void_reason,
  label: t.label, reply: t.reply, grade: t.grade, tone: t.tone, tone_rationale: t.tone_rationale,
  runtime_ms: t.runtime_ms,
  tool_calls: (t.tool_calls ?? []).length,
  tool_errors: (t.tool_calls ?? []).filter((c) => c.error).length,
  tokens: t.usage ? (t.usage.input_tokens ?? 0) + (t.usage.output_tokens ?? 0) : null,
  cost_usd: t.usage?.cost_usd,
});

function report(extra = {}) {
  return {
    round: ROUND,
    configs: CONFIGS,
    dry_run: !!ONLY,
    trials_per_cell: TRIALS,
    halted: halt,
    budget: { ...budget, spentUsd: Math.round(budget.spentUsd * 100) / 100 },
    trials: [...trials, ...topups].map(compact),
    ...extra,
  };
}

// ---------- Phase: Trials ----------
phase('Trials');
const baseSpecs = [];
for (const ticket of TICKETS) {
  for (const config of CONFIGS) {
    if (ONLY && !ONLY.has(cellKey(config, ticket))) continue;
    for (let n = 1; n <= TRIALS; n++) baseSpecs.push({ config, ticket, n, phaseName: 'Trials' });
  }
}
const RUN_TICKETS = [...new Set(baseSpecs.map((s) => s.ticket))];
log(`${ROUND}: ${CONFIGS.join(', ')} x ${RUN_TICKETS.length} tickets x ${TRIALS} trials = ${baseSpecs.length} trials. Cap $${CAP_USD}.`);
trials = await pipeline(baseSpecs, runTrial, voidIfPeeked);
if (halt) return report();

// ---------- Phase: Leak scan ----------
phase('Leak scan');
await transcriptScan(trials, 'Trials');
if (halt) return report();

// ---------- Phase: Grade ----------
phase('Grade');
await gradeTrials(trials, 'Trials');
if (halt) return report();

// ---------- Phase: Top-up ----------
phase('Top-up');
const cells = new Map();
for (const t of trials) {
  const k = cellKey(t.config, t.ticket);
  if (!cells.has(k)) cells.set(k, []);
  cells.get(k).push(t);
}
const mixed = [];
for (const [key, ts] of cells) {
  const graded = ts.filter((t) => t.grade);
  const passes = graded.filter((t) => t.grade.pass).length;
  if (passes > 0 && passes < graded.length) mixed.push({ key, config: ts[0].config, ticket: ts[0].ticket, passes, graded: graded.length });
}
mixed.sort((a, b) => a.key.localeCompare(b.key));
const topSpecs = [];
const unserved = [];
for (const m of mixed) {
  if (topSpecs.length + TOPUP.perCell > TOPUP.maxTrials) {
    unserved.push(m.key);
    continue;
  }
  for (let k = 1; k <= TOPUP.perCell; k++) topSpecs.push({ config: m.config, ticket: m.ticket, n: TRIALS + k, phaseName: 'Top-up' });
}
log(`top-up: ${mixed.length} mixed cells, ${topSpecs.length} extra trials, cap ${TOPUP.maxTrials}.${unserved.length ? ` No top-up for: ${unserved.join(', ')}.` : ''}`);
if (topSpecs.length) {
  topups = await pipeline(topSpecs, runTrial, voidIfPeeked);
  if (halt) return report({ mixed_cells: mixed });
  await transcriptScan(topups, 'Top-up');
  if (halt) return report({ mixed_cells: mixed });
  await gradeTrials(topups, 'Top-up');
  if (halt) return report({ mixed_cells: mixed });
}

// ---------- Phase: Judge (tone only, base trials only, blinded) ----------
phase('Judge');
const JUDGE_NOTE = 'The tone judge is Opus, which is the same model family as the Sonnet trial model. No judge from a different family is available, so tone scores can share Claude blind spots.';
log(JUDGE_NOTE);
const byTicket = new Map();
for (const t of trials.filter((x) => done(x) && x.reply)) {
  if (!byTicket.has(t.ticket)) byTicket.set(t.ticket, []);
  byTicket.get(t.ticket).push(t);
}
const judgeMissing = [];
await parallel(RUN_TICKETS.map((ticket) => async () => {
  const ts = byTicket.get(ticket) ?? [];
  if (!ts.length) return;
  if (!reserve('judge', ticket, EST.judgeUsd)) return;
  const rand = seeded(`${ROUND}:${ticket}`);
  const order = ts.map((t) => ({ t, k: rand() })).sort((a, b) => a.k - b.k).map((x) => x.t);
  const blind = order.map((t, i) => ({ reply_id: `R${i + 1}`, t }));
  const replies = blind.map((b) => `<reply id="${b.reply_id}">\n${b.t.reply}\n</reply>`).join('\n\n');
  let out = null;
  try {
    out = await agent(`You are the tone judge. Read ${JUDGE_RUBRIC} and apply its rubric exactly. Read the ticket at ${ticketPath(ticket)}. Do not read any other file under spe/.

Below are ${blind.length} draft first replies to that ticket, in random order. Different agent configurations wrote them, and you are not told which wrote which. Score each reply on tone only, on the rubric's scale. Ignore whether the category or priority is right. Return one score for every reply_id, and set scale_max to the top of the rubric's scale.

${replies}`, { label: `judge-${ticket}`, phase: 'Judge', schema: JUDGE_SCHEMA, model: JUDGE_MODEL });
  } catch (e) {
    log(`judge ${ticket} failed: ${String(e?.message ?? e)}`);
  }
  settle(EST.judgeUsd);
  const scores = new Map((out?.scores ?? []).map((s) => [s.reply_id, s]));
  if (out?.scale_max) toneScaleMax = out.scale_max;
  for (const b of blind) {
    const s = scores.get(b.reply_id);
    if (!s) {
      judgeMissing.push(b.t.trial_id);
      continue;
    }
    b.t.tone = s.tone;
    b.t.tone_rationale = s.rationale;
  }
}));
if (judgeMissing.length) log(`judge returned no score for ${judgeMissing.length} trials: ${judgeMissing.join(', ')}`);
if (halt) return report({ mixed_cells: mixed, judge_note: JUDGE_NOTE, judge_missing: judgeMissing });

// ---------- Phase: Synthesis ----------
phase('Synthesis');
function summarize(config) {
  const base = trials.filter((t) => t.config === config);
  const ok = base.filter(done);
  const graded = ok.filter((t) => t.grade);
  const withTop = [...graded, ...topups.filter((t) => t.config === config && done(t) && t.grade)];
  return {
    config,
    attempted: base.length,
    completed: ok.length,
    voided: base.filter((t) => t.voided).length,
    harness_errors: base.filter((t) => t.status === 'harness_error').length,
    rate_limited: base.filter((t) => t.status === 'rate_limited').length,
    skipped: base.filter((t) => t.status === 'skipped').length,
    category_acc: r3(mean(graded.map((t) => +t.grade.category_ok))),
    priority_acc: r3(mean(graded.map((t) => +t.grade.priority_ok))),
    both_acc: r3(mean(graded.map((t) => +t.grade.pass))),
    both_acc_with_topups: r3(mean(withTop.map((t) => +t.grade.pass))),
    tone_mean: r3(mean(ok.map((t) => t.tone))),
    tone_scale_max: toneScaleMax,
    runtime_ms_mean: r3(mean(ok.map((t) => t.runtime_ms))),
    tool_calls_mean: r3(mean(ok.map((t) => (t.tool_calls ?? []).length))),
    tool_errors_mean: r3(mean(ok.map((t) => (t.tool_calls ?? []).filter((c) => c.error).length))),
    tokens_mean: r3(mean(ok.map((t) => (t.usage ? (t.usage.input_tokens ?? 0) + (t.usage.output_tokens ?? 0) : NaN)))),
    cost_usd_mean: r3(mean(ok.map((t) => t.usage?.cost_usd))),
  };
}
const summary = CONFIGS.map(summarize);
const perCell = [...cells.entries()].map(([key, ts]) => ({
  cell: key,
  completed: ts.filter(done).length,
  passes: ts.filter((t) => t.grade?.pass).length,
  topups: topups.filter((t) => cellKey(t.config, t.ticket) === key && done(t)).length,
  topup_passes: topups.filter((t) => cellKey(t.config, t.ticket) === key && t.grade?.pass).length,
}));
const lowTone = toneScaleMax ? 0.6 * toneScaleMax : -Infinity;
const failing = [...trials, ...topups]
  .filter(done)
  .filter((t) => (t.grade && !t.grade.pass) || (typeof t.tone === 'number' && t.tone <= lowTone))
  .map(compact);

let analysis = null;
if (reserve('analysis', 'failure-analysis', EST.helperUsd)) {
  analysis = await agent(`You analyze the results of round ${ROUND} of the triage SPE loop. All trials are finished. You may read ${PREDICTIONS}, ${PLAN}, spe/failures.md, ${ANSWERS}, and the ticket files. Do not edit any file.

1. Score every prediction in ${PREDICTIONS} against the summary below. A prediction is a hit when the observed value falls inside predicted plus or minus band, and a miss otherwise. Name the grader check behind each number (grade.py category, grade.py priority, grade.py both, judge tone, or runner usage). If every config sits at the metric's maximum, mark that row not_scorable and set ceiling to true. Set all_hit to true only when every scorable row is a hit.
2. Group the failing trials into failures. Number them "${ROUND} F1", "${ROUND} F2", and so on. Each failure cites trial_ids and states its cause as a claim someone can check against the transcripts or the answers.
3. Propose changes for ${NEXT_ROUND}. Each proposal changes one thing and cites failure IDs. If ceiling is true, propose harder tasks and leave the decision to the user.
4. Count only completed trials. Harness errors, rate limits, skips, and voided trials are not model failures.

Summary: ${JSON.stringify(summary)}
Per cell: ${JSON.stringify(perCell)}
Failing trials: ${JSON.stringify(failing)}
Judge note: ${JUDGE_NOTE}`, { label: 'failure-analysis', phase: 'Synthesis', schema: ANALYSIS_SCHEMA, model: HELPER_MODEL });
  settle(EST.helperUsd);
}

let critic = null;
if (reserve('critic', 'completeness-critic', EST.helperUsd)) {
  critic = await agent(`You are the completeness critic for round ${ROUND} of the triage SPE loop. Do not edit any file. Check the run record below and list every gap. Check each of these:
- Every cell (${CONFIGS.length} configs x ${RUN_TICKETS.length} tickets) has ${TRIALS} completed trials, or each missing trial has a recorded status (harness_error, rate_limited, skipped, or voided).
- Every voided trial and every budget skip is listed with a reason.
- Every completed, non-voided trial has a grade.
- Every completed, non-voided base trial with a reply has a tone score, or it appears in judge_missing.
- Every prediction row in ${PREDICTIONS} appears in prediction_scores with a verdict and a grader check. You may read that file.
- Every failure cites at least one trial_id, and every proposal cites at least one failure ID.
- Metrics count only completed trials.
Set complete to true only when gaps is empty.

Summary: ${JSON.stringify(summary)}
Per cell: ${JSON.stringify(perCell)}
Budget: ${JSON.stringify(budget)}
Voided: ${JSON.stringify([...trials, ...topups].filter((t) => t.voided).map((t) => t.trial_id))}
Judge missing: ${JSON.stringify(judgeMissing)}
Analysis: ${JSON.stringify(analysis)}`, { label: 'completeness-critic', phase: 'Synthesis', schema: CRITIC_SCHEMA, model: HELPER_MODEL });
  settle(EST.helperUsd);
}

log(`${ROUND} done. Spent $${budget.spentUsd.toFixed(2)} of $${CAP_USD}. All predictions hit: ${analysis?.all_hit ?? 'unknown'}. Critic complete: ${critic?.complete ?? 'unknown'}.`);
return report({
  summary,
  per_cell: perCell,
  mixed_cells: mixed,
  topup_unserved: unserved,
  judge_note: JUDGE_NOTE,
  judge_missing: judgeMissing,
  analysis,
  critic,
});
```

The script has no filesystem access, so it returns everything in its result. After the run, I write that result to `spe/evals/results/r04.json` and commit it locally as the next SPE step.
